  mode?: "list" | "representative" | "adjacent"; time?: number; id?: string; direction?: -1 | 1 };
export type TimelineMarkerDetailResponse = { events: EventLogItem[]; nextCursor?: string; pageCursor?: string };

export function timelineMarkerStep(span: number, axisWidth: number, markerSpacingPx = 18) {
  const minimum = Math.max(0.001, span / 240, axisWidth > 0 ? span * markerSpacingPx / axisWidth : 0);
  const magnitude = 10 ** Math.floor(Math.log10(minimum));
  return TIMELINE_MARKER_STEPS.find(value => value >= minimum) ?? [1, 2, 5, 10].map(value => value * magnitude).find(value => value >= minimum)!;
}
/** This divides every display step allowed by span/240, including after resizing. */
export function timelineSummaryStep(span: number) {
  const steps = TIMELINE_MARKER_STEPS.filter(step => step >= Math.max(0.001, span / 240)).map(step => Math.round(step * 1000));
  const gcd = (a: number, b: number): number => b ? gcd(b, a % b) : a;
  return steps.length ? steps.reduce(gcd) / 1000 : 300;
}
export function timelineMarkerBucket(time: number, step: number) { return Math.floor(time * 1000 / Math.round(step * 1000)); }
export function timelineMarkerTarget(event: Pick<EventLogItem, "streamKey" | "flowKey" | "interfaceId">) {
  return JSON.stringify([event.streamKey ?? null, event.flowKey ?? null, event.streamKey || event.flowKey ? null : event.interfaceId ?? null]);
}
export function timelineRepresentativeOrder(a: TimelineMarkerEvent, b: TimelineMarkerEvent) {
  const severity = (event: TimelineMarkerEvent) => event.level === "error" ? 2 : event.level === "warn" ? 1 : 0;
  return severity(b) - severity(a) || b.time - a.time || b.id.localeCompare(a.id);
}
