type AnyRecord = Record<string, any>;
export type EventCountRecord = Pick<EventLogItem, "time" | "level" | "streamKey" | "flowKey">;

/** Count projections share severity rules, without building display labels or messages. */
export function normalizeEventCountRecord(raw: AnyRecord): EventCountRecord {
  const source = raw.source ?? {};
  return {
    time: Number(raw.time ?? Date.now() / 1000),
    level: levelForType(String(raw.type ?? "event"), raw.detail),
    streamKey: source.stream_key ? String(source.stream_key) : undefined,
    flowKey: source.flow_key ? String(source.flow_key) : undefined
  };
}

export function normalizeEventLine(line: string): EventLogItem | undefined {
