export function timelineBitrateScale(cells: TimelineBitrateCell[]) {
  const maximum = Math.max(0, ...cells.map(cell => cell.bps));
  if (!maximum) return null;
  const power = 10 ** Math.floor(Math.log10(maximum));
  return [1, 2, 5, 10].map(value => value * power).find(value => value >= maximum)!;
}

export function timelineBitrateLevel(bps: number, maximum: number) {
  if (!(maximum > 0) || !Number.isFinite(bps)) return 0;
  return Math.max(0, Math.min(5, Math.floor(Math.max(0, bps / maximum) * 6)));
}

export function formatTimelineBitrate(bps: number) {
  const units = ["bps", "Kbps", "Mbps", "Gbps", "Tbps"];
  let unit = 0;
  while (bps >= 1000 && unit < units.length - 1) { bps /= 1000; unit++; }
  return `${Number(bps.toFixed(2)).toLocaleString()} ${units[unit]}`;
}
